describe('Data Refresh After Mutation', () => {
  beforeEach(() => {
    cy.visit('/data-table');
  });

  it('should automatically refresh data after a successful mutation', () => {
    // Intercept the initial data fetch
    cy.intercept('GET', '/api/data').as('initialData');
    cy.wait('@initialData');

    // Verify initial data is displayed
    cy.get('[data-testid="data-row"]').should('be.visible');
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);

    // Intercept the mutation API call
    cy.intercept('POST', '/api/data/mutate').as('mutateData');

    // Perform mutation action
    cy.get('[data-testid="mutate-button"]').click();

    // Wait for mutation API call
    cy.wait('@mutateData');

    // Verify mutation success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Data updated successfully');

    // Verify data table refreshes by intercepting the subsequent GET request
    cy.intercept('GET', '/api/data').as('refreshedData');
    cy.wait('@refreshedData');

    // Verify data has been refreshed and updated
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="data-row"]').first().should('contain', 'Updated Value');
  });

  it('should handle mutation failure and not refresh data', () => {
    // Intercept initial data fetch
    cy.intercept('GET', '/api/data').as('initialData');
    cy.wait('@initialData');

    // Verify initial data is displayed
    cy.get('[data-testid="data-row"]').should('be.visible');

    // Intercept mutation API call and mock failure
    cy.intercept('POST', '/api/data/mutate', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('failedMutation');

    // Perform mutation action
    cy.get('[data-testid="mutate-button"]').click();

    // Wait for failed mutation API call
    cy.wait('@failedMutation');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to update data');

    // Verify data table does NOT refresh (no subsequent GET request)
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="data-row"]').first().should('contain', 'Original Value');
  });
});
